<?php
require __DIR__ . '/bootstrap.php'; require_login();try{$matches=supabase('GET','matches?select=*,first_user:profiles!matches_first_user_id_fkey(full_name,art_id),second_user:profiles!matches_second_user_id_fkey(full_name,art_id)&order=created_at.desc');$error='';}catch(Throwable $e){$matches=[];$error=$e->getMessage();}
$content='<div class="mb-4"><h2 class="h4">Match oversight</h2><p class="text-muted">Review all matches created on the platform.</p></div>'.($error?'<div class="alert alert-danger">'.e($error).'</div>':'').'<div class="card rounded-4 p-3 table-responsive"><table class="table align-middle"><thead><tr><th>Match</th><th>Participants</th><th>Created</th><th>Status</th></tr></thead><tbody>';
foreach($matches as $m){$a=$m['first_user']['full_name']??$m['first_user_id'];$b=$m['second_user']['full_name']??$m['second_user_id'];$content.='<tr><td>'.e(substr($m['id'],0,8)).'</td><td>'.e($a).' + '.e($b).'</td><td>'.e($m['created_at']??'').'</td><td>'.e($m['status']).'</td></tr>';}$content.='</tbody></table></div>';$title='Matches';page($title,$content);
